import{_ as p,a0 as s,w as o,s as b,ao as i,I as a,x as u,a1 as r,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Ubuntu 每日貼士:從Ubuntu 13.10升級到14.04(Trusty Tahr) [值得信賴的塔爾羊] | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 每日貼士:從Ubuntu 13.10升級到14.04(Trusty Tahr) [值得信賴的塔爾羊] | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 每日貼士:從Ubuntu 13.10升級到14.04(Trusty Tahr) [值得信賴的塔爾羊] | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 每日貼士:從Ubuntu 13.10升級到14.04(Trusty Tahr) [值得信賴的塔爾羊] | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/Daily Ubuntu Tips – Upgrade To Ubuntu 14.04 (Trusty Tahr) From 13.10","title":"Ubuntu 每日貼士:從Ubuntu 13.10升級到14.04(Trusty Tahr) [值得信賴的塔爾羊]","tag":"201402","desc":""},"relativePath":"201402/Daily Ubuntu Tips – Upgrade To Ubuntu 14.04 (Trusty Tahr) From 13.10.md","filePath":"[post].md"}'),d={name:"201402/Daily Ubuntu Tips – Upgrade To Ubuntu 14.04 (Trusty Tahr) From 13.10.md"};function T(l,t,U,m,g,f){const n=s("Link");return o(),b("div",null,[t[11]||(t[11]=i(`<h1 id="ubuntu-每日貼士-從ubuntu-13-10升級到14-04-trusty-tahr-值得信賴的塔爾羊" tabindex="-1">Ubuntu 每日貼士:從Ubuntu 13.10升級到14.04(Trusty Tahr) [值得信賴的塔爾羊] <a class="header-anchor" href="#ubuntu-每日貼士-從ubuntu-13-10升級到14-04-trusty-tahr-值得信賴的塔爾羊" aria-label="Permalink to “Ubuntu 每日貼士:從Ubuntu 13.10升級到14.04(Trusty Tahr) [值得信賴的塔爾羊]”">​</a></h1><p>雖然Ubuntu 14.04 按計劃不會近期發佈正式版，但那些想要嘗試最新軟件和系統的人現在可以從Ubuntu 13.10 就地升級到 14.04了。</p><p>Ubuntu 14.04 目前計劃在2014.4.17發佈，但是你不必等那麼長的時間來升級嘗試。這個簡要的教程給你展示瞭如何就地從Ububtu 13.10 升級到 14.04。</p><p>就地升級是你在已存在的Ubuntu上運行update-manager命令來升級到下一版。它允許你保留你大多數的文檔，設定和一些程序。</p><p>大多數就地升級依賴於一個可靠的網絡連接。沒有良好穩定的連接,可能無法使用這個方法升級Ubuntu。</p><p>如果你無法使用網絡升級，你還可以通過CD/DVD盤來就地升級。這個方法允許你不通過網絡連接離線升級Ubuntu。</p><h3 id="升級到-ubuntu-14-04" tabindex="-1">升級到 Ubuntu 14.04 <a class="header-anchor" href="#升級到-ubuntu-14-04" aria-label="Permalink to “升級到 Ubuntu 14.04”">​</a></h3><p>為了升級到Ubuntu 14.04, 你首先要給你要升級的電腦做好準備工作。請運行下面的命令更新所有存在的包和內核。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade &amp;&amp; sudo apt-get autoremove
</code></pre><p>完成上述更新後，你可能需要重啓來在升級前應用新的包和內核。</p><p>接着，按下鍵盤上的<strong>Alt+F2</strong>鍵來打開Ubuntu上的命令窗口。當窗口打開後，輸入下面的命令並按下<strong>回車</strong>。</p><pre><code>update-manager –d
</code></pre><p>Ubuntu接着應該帶着升級選項會打開update-manager。按下<strong>Upgrade</strong> 開始升級你的機器。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/01/ubuntu1404upgrade.png" alt=""></p><p>就是這樣!</p><p>等待Ubuntu完成下載並安裝所有的更新包。當一切完成時,你會被提示重啓計算機。</p><p>享受吧!</p><hr>`,18)),a("p",null,[t[1]||(t[1]=u("via: ",-1)),r(n,{href:"http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-upgrade-to-ubuntu-14-04-trusty-tahr-from-13-10/"},{default:e(()=>[...t[0]||(t[0]=[u("http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-upgrade-to-ubuntu-14-04-trusty-tahr-from-13-10/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=u("譯者：",-1)),r(n,{href:"https://github.com/geekpi"},{default:e(()=>[...t[2]||(t[2]=[u("geekpi",-1)])]),_:1}),t[5]||(t[5]=u(" 校對：",-1)),r(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[3]||(t[3]=[u("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=u("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原創翻譯，",-1)),r(n,{href:"http://linux.cn/"},{default:e(()=>[...t[7]||(t[7]=[u("Linux中國",-1)])]),_:1}),t[10]||(t[10]=u(" 榮譽推出",-1))])])}const C=p(d,[["render",T]]);export{_ as __pageData,C as default};
